LOOK = [("← →", "var(--pink)"), ("↓", "var(--green)"), ("↑", "var(--orange)"), ("!", "var(--blue)")]


def steps(code: str) -> list:
    return [(g, c, h, p) for (g, c), (h, p) in zip(LOOK, STEPS[code])]
